#!/bin/bash\n\n# smg4OS Full System Setup\n# \"Let's set up EVERYTHING!\"\n\nset -e\n\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nWIZARD_DIR=\"$(dirname \"$SCRIPT_DIR\")\"\n\n# Source color definitions\nsource \"$WIZARD_DIR/scripts/colors.sh\"\n\nsmg4_say \"Alright, buckle up! We're doing a FULL system setup!\"\nsleep 1\n\necho \"\"\necho -e \"${BLUE}════════════════════════════════════════════════════════════════${NC}\"\necho -e \"${BLUE}  FULL SYSTEM SETUP${NC}\"\necho -e \"${BLUE}════════════════════════════════════════════════════════════════${NC}\"\necho \"\"\n\n# System hostname\necho \"${GOLD}Step 1: System Hostname${NC}\"\nread -p \"Enter hostname (default: smg4-workstation): \" hostname\nhostname=\"${hostname:-smg4-workstation}\"\nsmg4_say \"Setting hostname to: $hostname\"\n\n# Desktop environment\necho \"\"\necho \"${GOLD}Step 2: Desktop Environment${NC}\"\necho \"Which desktop would you like?\"\necho \"  1) XFCE (Lightweight, recommended)\"\necho \"  2) Openbox (Super minimal)\"\necho \"  3) None (Headless/minimal)\"\nread -p \"Choose [1-3]: \" de_choice\n\ncase $de_choice in\n    1) de=\"xfce4\" ;; \n    2) de=\"openbox\" ;;\n    3) de=\"none\" ;;\n    *) de=\"xfce4\" ;; \nesac\n\nsmg4_say \"Setting up $de\"\n\n# Theme selection\necho \"\"\necho \"${GOLD}Step 3: Theme Selection${NC}\"\necho \"Which theme would you like?\"\necho \"  1) smg4 Dark (Official - with gold accents)\"\necho \"  2) Adwaita (Classic GNOME)\"\necho \"  3) None (System default)\"\nread -p \"Choose [1-3]: \" theme_choice\n\ncase $theme_choice in\n    1) theme=\"smg4\" ;;\n    2) theme=\"Adwaita\" ;;\n    3) theme=\"none\" ;;\n    *) theme=\"smg4\" ;;\nesac\n\nsmg4_say \"Theme set to: $theme\"\n\n# User creation\necho \"\"\necho \"${GOLD}Step 4: User Account${NC}\"\nread -p \"Enter username (default: gamer): \" username\nusername=\"${username:-gamer}\"\n\nif ! id \"$username\" &>/dev/null 2>&1; then\n    smg4_say \"Creating user: $username\"\n    # This would normally create the user, but we'll skip in simulation\n    # sudo useradd -m -s /bin/bash \"$username\"\nelse\n    smg4_say \"User $username already exists!\"\nfi\n\n# Additional packages\necho \"\"\necho \"${GOLD}Step 5: Additional Packages${NC}\"\necho \"Install additional packages?\"\necho \"  1) Gaming tools (Steam, Lutris, Proton)\"\necho \"  2) Development tools (Git, GCC, Make, etc.)\"\necho \"  3) Multimedia (GIMP, Inkscape, FFmpeg)\"\necho \"  4) None (Minimal installation)\"\nread -p \"Choose [1-4]: \" packages_choice\n\ncase $packages_choice in\n    1) \n        smg4_say \"Installing gaming packages...\"\n        packages_type=\"gaming\"\n        ;;\n    2)\n        smg4_say \"Installing development tools...\"\n        packages_type=\"dev\"\n        ;;\n    3)\n        smg4_say \"Installing creative tools...\"\n        packages_type=\"creative\"\n        ;;\n    *)\n        smg4_say \"Sticking with minimal installation.\"\n        packages_type=\"minimal\"\n        ;;\nesac\n\n# Summary\necho \"\"\necho -e \"${BLUE}════════════════════════════════════════════════════════════════${NC}\"\necho -e \"${BLUE}  SETUP SUMMARY${NC}\"\necho -e \"${BLUE}════════════════════════════════════════════════════════════════${NC}\"\necho \"\"\necho -e \"${WHITE}Hostname:${NC}           $hostname\"\necho -e \"${WHITE}Desktop:${NC}            $de\"\necho -e \"${WHITE}Theme:${NC}              $theme\"\necho -e \"${WHITE}Username:${NC}           $username\"\necho -e \"${WHITE}Packages:${NC}           $packages_type\"\necho \"\"\n\nread -p \"Does everything look good? (y/n) \" confirm\n\nif [[ $confirm == \"y\" || $confirm == \"Y\" ]]; then\n    echo \"\"\n    smg4_say \"Let's get this show on the road!\"\n    sleep 1\n    \n    # Apply settings (simulated)\n    smg4_success \"Hostname configured\"\n    smg4_success \"Desktop environment configured\"\n    smg4_success \"Theme applied\"\n    smg4_success \"User account ready\"\n    smg4_success \"Packages marked for installation\"\n    \n    echo \"\"\n    smg4_say \"All set! Your system is configured and ready to go.\"\n    smg4_say \"To apply changes, run: sudo systemctl reboot\"\nelse\n    smg4_say \"No problem! Let's try again.\"\n    exec \"$WIZARD_DIR/smg4-setup.sh\"\nfi\n"